# Runs the delivered program with an audit hook that reports every file open and process
# start to the descriptor named on its command line, which the verifier reads.
_AUDIT_WRAPPER = r'''
import json, os, runpy, sys
_fd = int(sys.argv[1])
_prog = sys.argv[2]
_sink = os.fdopen(_fd, "w", buffering=1)
def _hook(event, args):
    try:
        if event == "open":
            path, mode, flags = args
            if isinstance(path, int):
                return
            writes = isinstance(mode, str) and any(ch in mode for ch in "wax+")
            if isinstance(flags, int) and flags & (os.O_WRONLY | os.O_RDWR | os.O_CREAT | os.O_APPEND):
                writes = True
            _sink.write(json.dumps(["open", os.fsdecode(path), writes]) + "\n")
        elif event in ("subprocess.Popen", "os.system", "os.exec", "os.posix_spawn", "os.spawn", "os.fork"):
            _sink.write(json.dumps(["process", event, ""]) + "\n")
        elif event.startswith("socket."):
            _sink.write(json.dumps(["socket", event, ""]) + "\n")
    except Exception:
        pass
sys.addaudithook(_hook)
sys.argv = [_prog] + sys.argv[3:]
sys.path[0] = os.path.dirname(os.path.abspath(_prog))
runpy.run_path(_prog, run_name="__main__")
'''


# ---------------------------------------------------------------- extract generator

EPOCH = datetime(2000, 1, 1)
REGIONS = ["central", "east", "north", "south", "west"]
SEGMENTS = ["consumer", "corporate", "enterprise", "smb"]
SLOT_SEC = 60
TIERS = ["standard", "after_hours", "weekend_holiday"]


def _sec(dt: datetime) -> int:
    return int((dt - EPOCH).total_seconds())


def _iso(sec: int) -> str:
    return (EPOCH + timedelta(seconds=sec)).strftime("%Y-%m-%dT%H:%M:%S")


def _legacy(sec: int) -> str:
    return (EPOCH + timedelta(seconds=sec)).strftime("%d.%m.%Y %H:%M:%S")


def _day(d: int) -> str:
    return (EPOCH + timedelta(days=d)).strftime("%Y-%m-%d")


def _csv(header: list[str], rows: list[list]) -> str:
    buf = io.StringIO()
    w = csv.writer(buf, lineterminator="\n")
    w.writerow(header)
    for r in rows:
        w.writerow(r)
    return buf.getvalue()


SERVICE_POOL = [
    ("calendar", ["CAL", "AGD", "MTG"]), ("travel", ["TRV", "BKG", "VIS"]), ("errands", ["ERR", "DLV", "PCK"]),
    ("correspondence", ["COR", "MAIL", "LTR"]), ("research", ["RSC", "BRF", "CMP"]), ("events", ["EVT", "VEN"]),
    ("household", ["HSE", "MNT"]), ("finance_admin", ["FIN", "INV"]),
]
ZONE_POOL = [("Z-ATLANTIC", 0), ("Z-MERIDIAN", 60), ("Z-LEVANT", 120), ("Z-AZORES", -60), ("Z-CASPIAN", 180), ("Z-ISLES", 0)]


def build(seed: int, prof: dict) -> tuple[dict[str, str], dict]:
    rng = random.Random(seed)
    shipped = prof.get("shipped", False)
    base = prof.get("base", shipped)
    plant = prof.get("plant", not shipped)
    first = (datetime.strptime(prof["first_day"], "%Y-%m-%d") - EPOCH).days
    n_days = prof["n_days"]
    last = first + n_days - 1
    days = list(range(first, last + 1))

    # zones
    zsel = prof.get("zones") or rng.sample(ZONE_POOL[:4], 3)
    zone_rows = []
    zone_off = {}
    for z, base in zsel:
        zone_rows.append([z, "2000-01-01T00:00:00", base])
        zone_off[z] = [(0, base)]
    dst = prof.get("dst")
    if dst:
        z, di, delta = dst
        base = dict(zsel)[z]
        t = (days[di]) * 86400 + prof.get("dst_hour", 2) * 3600 - 60 * base
        step_at = t
        zone_rows.append([z, _iso(t), base + delta])
        zone_off[z].append((t, base + delta))
        if prof.get("dst_back"):
            di2 = prof["dst_back"]
            t2 = days[di2] * 86400 + 2 * 3600 - 60 * (base + delta)
            zone_rows.append([z, _iso(t2), base])
            zone_off[z].append((t2, base))

    def zoff(z, t):
        o = None
        for frm, m in zone_off[z]:
            if frm <= t:
                o = m
        return o

    # catalog
    pool = SERVICE_POOL[:5] if base else rng.sample(SERVICE_POOL, rng.randint(4, 6))
    services = []
    for pl, stems in pool:
        for st in rng.sample(stems, min(len(stems), 2)):
            code = f"{st}-{rng.randint(10, 99)}"
            while code in [s[0] for s in services]:
                code = f"{st}-{rng.randint(10, 99)}"
            services.append((code, pl, rng.choice([5, 6, 10, 15])))
    aliases = []
    for code, _pl, _inc in rng.sample(services, 3):
        aliases.append((f"OLD{rng.randint(100, 999)}", code))
    # rate cards
    card_from = first - 400
    rates = {}
    rate_rows = []
    boundary = prof.get("rate_boundary")
    split_day = days[boundary] if boundary is not None else last + 3
    split_keys = set()
    for code, _pl, _inc in services:
        for tier in TIERS:
            base = rng.randint(9, 30) * 50000 + rng.choice([0, 0, 17000, 33000])
            if tier == "after_hours":
                base = base * 3 // 2
            if tier == "weekend_holiday":
                base = base * 2
            rates[(code, tier)] = base
    pick = rng.sample(sorted(rates), max(3, len(rates) // 3))
    for key in sorted(rates):
        code, tier = key
        if key in pick:
            new = rates[key] + rng.randint(1, 9) * 10000
            rate_rows.append([code, tier, rates[key], _day(card_from), _day(split_day)])
            rate_rows.append([code, tier, new, _day(split_day), ""])
            split_keys.add(key)
        else:
            rate_rows.append([code, tier, rates[key], _day(card_from), ""])
    gap_key = None
    if prof.get("unrated"):
        gap_key = rng.choice(sorted(k for k in rates if k[1] == "after_hours" and k not in split_keys))
        rate_rows = [r for r in rate_rows if (r[0], r[1]) != gap_key]
        gday = days[rng.randint(3, n_days - 4)]
        rate_rows.append([gap_key[0], gap_key[1], rates[gap_key], _day(card_from), _day(gday)])
        rate_rows.append([gap_key[0], gap_key[1], rates[gap_key] + 20000, _day(gday + 2), ""])
    decoy_rows = []
    for code, tier, rate, frm, to in rate_rows:
        decoy_rows.append([code, tier, rate - rng.randint(1, 6) * 7000, frm, to])
    if not base:
        for r in rng.sample(decoy_rows, len(decoy_rows) // 3):
            r[2] = r[2] + rng.randint(2, 9) * 11000
    rng.shuffle(rate_rows)
    rng.shuffle(decoy_rows)

    # plans
    plans = [("P-BASIC", rng.choice([60, 90, 120]), "standard"),
             ("P-PLUS", rng.choice([180, 240, 300]), "standard after_hours"),
             ("P-EXEC", rng.choice([480, 600]), "standard after_hours weekend_holiday")]
    if not base and rng.random() < 0.5:
        plans.append((f"P-{rng.choice(['LITE', 'FLEX', 'NOMAD'])}", rng.choice([0, 45, 150]), rng.choice(["after_hours", "standard weekend_holiday"])))

    # holidays
    holidays = []
    for region in rng.sample(REGIONS, 2):
        wk = [d for d in days if (EPOCH + timedelta(days=d)).weekday() < 5]
        holidays.append((region, rng.choice(wk[2:-2]), rng.choice(["Founders Day", "Harvest Day", "Lantern Day", "Charter Day"])))
    if plant:
        r0, d0, n0 = holidays[0]
        holidays[0] = (r0, d0, n0 + ", observed")

    # handsets and clients
    nh = prof["n_handsets"]
    hnames = sorted(rng.sample(range(1, 40), nh))
    handsets = [f"H-{i:02d}" for i in hnames]
    legacy = set(rng.sample(handsets, prof.get("n_legacy", 2)))
    nc = prof["n_clients"]
    client_ids = sorted(rng.sample(range(100, 999), nc))
    lines = rng.sample(range(2000, 2999), nc)
    clients = []
    for i, cid in enumerate(client_ids):
        region = REGIONS[i % 5] if i < 5 else rng.choice(REGIONS)
        seg = SEGMENTS[i % 4] if i < 4 else rng.choice(SEGMENTS)
        plan = rng.choice(plans)[0]
        zone = rng.choice(zsel)[0]
        clients.append({"client": f"C-{cid:04d}", "line": f"L-{lines[i]}", "segment": seg, "region": region,
                        "plan": plan, "zone": zone})
    if dst:
        for c in clients[:max(3, nc // 4)]:
            c["zone"] = dst[0]
    serve = {h: [] for h in handsets}
    order = list(clients)
    rng.shuffle(order)
    for i, c in enumerate(order):
        serve[handsets[i % nh]].append(c["client"])
    share = prof.get("share")
    shared_clients = {}
    if share:
        comp = rng.sample(handsets, share)
        for i, h in enumerate(comp):
            nxt = comp[(i + 1) % len(comp)]
            for cid in serve[h][: prof.get("share_depth", 2)]:
                shared_clients.setdefault(cid, {h}).add(nxt)
                if rng.random() < 0.4:
                    shared_clients[cid].add(rng.choice(comp))
    cmap = {c["client"]: c for c in clients}
    served_by = {c["client"]: set() for c in clients}
    for h, cl in serve.items():
        for cid in cl:
            served_by[cid].add(h)
    for cid, hs in shared_clients.items():
        served_by[cid] |= hs
    hclients = {h: sorted(cid for cid in served_by if h in served_by[cid]) for h in handsets}

    # offsets
    base_off = {h: rng.randint(-15, 15) for h in handsets}
    changes = []
    cum = {}
    for hi, di, delta in prof.get("changes", []):
        h = handsets[hi]
        now = base_off[h] + cum.get(h, 0)
        if delta == "back":
            delta = -cum.get(h, 0)
        elif not -19 <= now + delta <= 19:
            delta = -delta
        cum[h] = cum.get(h, 0) + delta
        changes.append((hi, di, delta))

    def offset(h, d):
        o = base_off[h]
        for hi, di, delta in changes:
            if handsets[hi] == h and d >= days[di]:
                o += delta
        return max(-19, min(19, o))

    # closings
    closings = []
    codes = [s[0] for s in services]
    inc_of = {s[0]: s[2] for s in services}
    pl_of = {s[0]: s[1] for s in services}

    def add(h, cid, true_sec, code=None, worked=None):
        closings.append({"handset": h, "client": cid, "true": true_sec, "code": code or rng.choice(codes),
                         "worked": worked or rng.randint(3, 95)})

    for d in days:
        wd = (EPOCH + timedelta(days=d)).weekday()
        for h in handsets:
            n = rng.randint(*(prof.get("per_day", (7, 15)) if wd < 5 else (2, 5)))
            for _ in range(n):
                cid = rng.choice(hclients[h])
                add(h, cid, d * 86400 + rng.randint(4 * 3600, 21 * 3600 + 1800))

    planted = []
    late_pair = []
    xrng = random.Random(seed * 31 + 7)
    if plant:
        # closings exactly on tier edges, and near local midnight at the end of the cycle
        for _ in range(prof.get("edges", 24)):
            cid = rng.choice(clients)["client"]
            h = rng.choice(sorted(served_by[cid]))
            wk = [d for d in days if (EPOCH + timedelta(days=d)).weekday() < 5]
            d = rng.choice(wk)
            lt = d * 86400 + rng.choice([8, 18]) * 3600
            t = lt - 60 * zoff(cmap[cid]["zone"], lt)
            add(h, cid, t)
            planted.append(("edge", t))
            if t + 60 * zoff(cmap[cid]["zone"], t) == lt and lt % 86400 == 18 * 3600:
                closings[-1]["plant"] = "edge18"
        pos = [c for c in clients if dict(zsel)[c["zone"]] > 0] or clients
        for _ in range(2):
            c = rng.choice(pos)
            h = rng.choice(sorted(served_by[c["client"]]))
            lt = (last + 1) * 86400 + rng.randint(-10, 10) * 60 + rng.randint(1, 50)
            t = lt - 60 * zoff(c["zone"], lt)
            if 4 * 3600 <= t % 86400 <= 21 * 3600 + 1800:
                add(h, c["client"], t)
        # a closing completed exactly at the zone step instant
        if dst:
            zc = [c for c in clients if c["zone"] == dst[0]]
            c = xrng.choice(zc) if zc else None
            if c and 3600 <= step_at % 86400 <= 86400 - 3600:
                add(xrng.choice(sorted(served_by[c["client"]])), c["client"], step_at)
                closings[-1]["plant"] = "zone_step"
        # the day after the cycle: one closing to be rejected and one to be voided
        for _ in range(2):
            c = xrng.choice(clients)
            h = xrng.choice(sorted(served_by[c["client"]]))
            lt = (last + 1) * 86400 + xrng.randint(10 * 3600, 15 * 3600)
            add(h, c["client"], lt - 60 * zoff(c["zone"], lt))
            late_pair.append(closings[-1])
        # a tie at the point where a basic allowance runs out: the credit tie-break decides who is credited
        basic = [c for c in clients if c["plan"] == "P-BASIC"]
        for c in xrng.sample(basic, min(9, len(basic))):
            off_days = {d for r, d, _n in holidays if r == c["region"]}
            wk = [d for d in days if (EPOCH + timedelta(days=d)).weekday() < 5 and d not in off_days]
            hs = sorted(served_by[c["client"]])
            lt = wk[-1] * 86400 + 17 * 3600 + 59 * 60 + xrng.randint(0, 30)
            t = lt - 60 * zoff(c["zone"], lt)
            code_a, code_b = xrng.sample(codes, 2)
            add(xrng.choice(hs), c["client"], t, code=code_a, worked=95)
            closings[-1]["plant"] = "tie"
            add(xrng.choice(hs), c["client"], t, code=code_b, worked=80)
            closings[-1]["plant"] = "tie"
        # ties: two closings of one client with the same completion instant
        for _ in range(prof.get("ties", 2)):
            cid = rng.choice(clients)["client"]
            hs = sorted(served_by[cid])
            d = rng.choice(days)
            t = d * 86400 + rng.randint(9 * 3600, 16 * 3600)
            add(rng.choice(hs), cid, t)
            add(rng.choice(hs), cid, t)
        # closings sensitive to each change: within the shift of a tier edge on changed days
        for hi, di, delta in changes:
            h = handsets[hi]
            for d in days[di:di + 3]:
                if (EPOCH + timedelta(days=d)).weekday() >= 5:
                    continue
                cid = rng.choice(hclients[h])
                lt = d * 86400 + 18 * 3600 + (rng.randint(1, abs(delta)) * 60 - 30) * (1 if delta > 0 else -1)
                t = lt - 60 * zoff(cmap[cid]["zone"], lt)
                if 4 * 3600 <= t % 86400 <= 21 * 3600 + 1800:
                    add(h, cid, t)
    if dst:
        z = dst[0]
        zc = [c["client"] for c in clients if c["zone"] == z]
        td = days[dst[1]]
        for d in (td - 1, td, td + 1):
            for _ in range(3):
                cid = rng.choice(zc)
                h = rng.choice(sorted(served_by[cid]))
                lt = d * 86400 + rng.choice([rng.randint(7 * 3600 + 3000, 8 * 3600 + 600), rng.randint(17 * 3600 + 3000, 18 * 3600 + 600)])
                t = lt - 60 * zoff(z, lt)
                if 4 * 3600 <= t % 86400 <= 21 * 3600 + 1800:
                    add(h, cid, t)
    if boundary is not None:
        for key in sorted(split_keys)[:3]:
            code, tier = key
            for d in (split_day - 1, split_day):
                if tier == "weekend_holiday" or (EPOCH + timedelta(days=d)).weekday() >= 5:
                    continue
                cid = rng.choice(clients)["client"]
                h = rng.choice(sorted(served_by[cid]))
                hour = 11 if tier == "standard" else 20
                lt = d * 86400 + hour * 3600 + rng.randint(0, 1800)
                t = lt - 60 * zoff(cmap[cid]["zone"], lt)
                if 4 * 3600 <= t % 86400 <= 21 * 3600 + 1800:
                    add(h, cid, t, code=code)

    # echoes: on a weekend day one handset closes a run of tasks on another handset's client line, each a fixed
    # number of minutes before that handset's own closings there, and the exchange loses the first handset's calls
    erng = random.Random(seed * 13 + 5)
    weekend = [d for d in days if (EPOCH + timedelta(days=d)).weekday() >= 5]
    for _ in range(prof.get("echo", 3) if weekend else 0):
        d = erng.choice(weekend)
        g, h = erng.sample(handsets, 2)
        if not hclients[g]:
            continue
        cid = erng.choice(hclients[g])
        delta = erng.choice([k for k in range(-12, 13) if abs(k) >= 2 and -19 <= offset(h, d) + k <= 19])
        start = 9 * 60 + erng.randint(0, 120)
        for i in range(8):
            y = start + i * (2 * abs(delta) + 3 + erng.randint(0, 4))
            add(g, cid, d * 86400 + y * 60 + erng.randint(5, 50))
            add(h, cid, d * 86400 + (y - delta) * 60 + erng.randint(5, 50))
            closings[-1]["lost"] = True

    # unknown service codes
    for c in rng.sample(closings, max(2, len(closings) // 250)):
        c["code"] = f"ZZ-{rng.randint(100, 999)}"
    # past the cycle end: one rejected closing and one void closing (exclusion order of the quality lists)
    late_void = None
    if late_pair:
        late_pair[0]["code"] = f"ZZ-{rng.randint(100, 999)}"
        late_void = late_pair[1]
    # alias use on legacy handsets
    alias_of = {}
    for a, code in aliases:
        alias_of.setdefault(code, a)

    # stamps, sequence numbers, references
    for c in closings:
        d = c["true"] // 86400
        c["offset"] = offset(c["handset"], d)
        c["stamp"] = c["true"] - 60 * c["offset"]
    closings.sort(key=lambda c: (c["handset"], c["stamp"], c["true"]))
    seqn = {}
    refs = rng.sample(range(100000, 999999), len(closings))
    for i, c in enumerate(closings):
        seqn[c["handset"]] = seqn.get(c["handset"], 0) + 1
        c["seq"] = seqn[c["handset"]]
        c["ref"] = f"CL-{refs[i]}"
        c["shown_code"] = c["code"]
        if c["handset"] in legacy and c["code"] in alias_of and rng.random() < 0.5:
            c["shown_code"] = alias_of[c["code"]]
        if rng.random() < 0.03:
            c["shown_code"] = c["shown_code"].lower()

    # amendments
    amends = []
    aid = rng.sample(range(1000, 9999), 400)
    k = 0

    def amend(issued, action, c=None, minutes=None, reverts=None, hs=None, seq=None):
        nonlocal k
        a = {"action": action, "amendment": f"A-{aid[k]}", "handset": hs if hs else (c["handset"] if c else None),
             "issued_at": _iso(issued), "minutes": minutes, "reverts": reverts,
             "seq": seq if seq else (c["seq"] if c else None)}
        k += 1
        amends.append(a)
        return a

    for c in rng.sample(closings, max(3, len(closings) // 120)):
        amend(c["true"] + rng.randint(3600, 86400 * 2), "void", c)
    if late_void is not None:
        amend(late_void["true"] + 5400, "void", late_void)
    for c in rng.sample(closings, max(4, len(closings) // 80)):
        amend(c["true"] + rng.randint(1800, 86400 * 3), "minutes", c, minutes=rng.randint(5, 120))
    if prof.get("amend_extra", not shipped):
        for c in rng.sample(closings, 3):
            a = amend(c["true"] + rng.randint(3600, 40000), rng.choice(["void", "minutes"]), c, minutes=rng.randint(5, 90))
            if a["action"] == "void":
                a["minutes"] = None
            amend(c["true"] + rng.randint(50000, 90000), "revert", reverts=a["amendment"])
        for c in rng.sample([c for c in closings if abs(c["offset"]) >= 3], 3):
            lo, hi = sorted((c["stamp"], c["true"]))
            issued = rng.randint(lo + 1, hi - 1)
            a = amend(issued, "minutes", c, minutes=rng.randint(5, 90))
        c = rng.choice(closings)
        a = amend(c["true"] + 7200, "void", c)
        amend(c["true"] + 3600, "revert", reverts=a["amendment"])
        amend(rng.choice(closings)["true"] + 5000, "void", hs=rng.choice(handsets), seq=9999)
        c = rng.choice(closings)
        t = c["true"] + 9000
        a1 = amend(t, "minutes", c, minutes=rng.randint(5, 60))
        a2 = amend(t, "minutes", c, minutes=rng.randint(61, 119))
        # reverts that name a revert, and one that names no amendment
        c = rng.choice(closings)
        a = amend(c["true"] + 3000, "void", c)
        r = amend(c["true"] + 6000, "revert", reverts=a["amendment"])
        amend(c["true"] + 9000, "revert", reverts=r["amendment"])
        amend(c["true"] + 9500, "revert", reverts="A-0000")
        # issue instants on the edges: a void issued at the completion instant, a revert issued with its target
        for c in rng.sample([c for c in closings if "plant" not in c and c["handset"] not in legacy], prof.get("edge_amends", 12)):
            amend(c["true"], "void", c)
            c["plant"] = "amend_eq"
        for c in rng.sample([c for c in closings if "plant" not in c and c["handset"] not in legacy], prof.get("edge_amends", 12)):
            a = amend(c["true"] + 4000, "void", c)
            amend(c["true"] + 4000, "revert", reverts=a["amendment"])
            c["plant"] = "revert_eq"
    rng.shuffle(amends)

    # exports
    main_rows, legacy_rows, dup_rows = [], [], []
    unit = prof.get("legacy_unit", "seconds")
    for c in closings:
        if c["handset"] in legacy:
            dur = c["worked"] if unit == "minutes" else c["worked"] * 60 - rng.randint(0, 59)
            legacy_rows.append([c["ref"], c["handset"], c["seq"], c["client"], c["shown_code"], _legacy(c["stamp"]), dur])
        else:
            main_rows.append([c["ref"], c["handset"], c["seq"], c["client"], c["shown_code"], _iso(c["stamp"]), c["worked"]])
    legacy_cl = [c for c in closings if c["handset"] in legacy]
    for c in rng.sample(legacy_cl, min(len(legacy_cl), prof.get("dups", 4))):
        main_rows.append([c["ref"], c["handset"], c["seq"], c["client"], c["code"], _iso(c["stamp"]), c["worked"]])
        if prof.get("dup_differ", not shipped):
            for r in legacy_rows:
                if r[0] == c["ref"]:
                    r[6] = (c["worked"] + rng.randint(7, 30)) * (60 if unit == "seconds" else 1)
    rng.shuffle(main_rows)
    rng.shuffle(legacy_rows)

    # register
    reg = {}
    for c in closings:
        if c.get("lost"):
            continue
        d, sod = divmod(c["true"], 86400)
        key = (d, sod // SLOT_SEC * SLOT_SEC, cmap[c["client"]]["line"])
        reg[key] = reg.get(key, 0) + 1
    drop = prof.get("drop", 0.04)
    for key in sorted(reg):
        if rng.random() < drop:
            reg[key] -= 1
    reg_rows = [[_day(d), f"{s // 3600:02d}:{s % 3600 // 60:02d}", line, n] for (d, s, line), n in reg.items() if n > 0]
    rng.shuffle(reg_rows)

    minimum = prof.get("minimum_invoice_micro")
    cycle_name = prof.get("cycle", "C" + _day(first)[:7].replace("-", ""))
    card_name, decoy_name = ("rate_card_final.csv", "rate_card.csv") if prof.get("final_current") else ("rate_card.csv", "rate_card_final.csv")
    header = {"cycle": cycle_name, "first_day": _day(first), "last_day": _day(last), "rate_card": card_name,
              "minimum_invoice_micro": minimum if minimum is not None else 0}
    rate_head = ["service", "tier", "rate_micro_per_minute", "effective_from", "effective_to"]
    files = {
        "cycle.json": json.dumps(header, indent=2) + "\n",
        "clients.csv": _csv(["client", "line", "segment", "region", "plan", "zone"],
                            [[c["client"], c["line"], c["segment"], c["region"], c["plan"], c["zone"]] for c in clients]),
        "plans.csv": _csv(["plan", "included_minutes", "credit_tiers"], [list(p) for p in plans]),
        "zone_rules.csv": _csv(["zone", "from_utc", "utc_offset_minutes"], zone_rows),
        "holidays.csv": _csv(["region", "day", "name"], [[r, _day(d), n] for r, d, n in holidays]),
        "service_catalog.csv": _csv(["service", "product_line", "increment_minutes"], [list(s) for s in services]),
        "code_aliases.csv": _csv(["alias", "service"], [list(a) for a in aliases]),
        card_name: _csv(rate_head, rate_rows),
        decoy_name: _csv(rate_head, decoy_rows),
        "closings.csv": _csv(["ref", "handset", "seq", "client", "service", "stamped_at", "worked_minutes"], main_rows),
        "legacy_closings.txt": "# legacy handset export\n# fields: ref|handset|seq|client|service|stamped|duration\n"
                               f"# duration unit: {unit}\n"
                               + "".join(" | ".join(str(v) for v in r) + "\n" + ("\n" if plant and i == len(legacy_rows) // 2 else "")
                                         for i, r in enumerate(legacy_rows)),
        "exchange_register.csv": _csv(["day", "slot", "line", "calls"], reg_rows),
        "amendments.jsonl": "".join(json.dumps(a, sort_keys=True) + "\n" for a in amends),
    }
    if prof.get("bom"):
        files["clients.csv"] = "﻿" + files["clients.csv"]
    meta = {"trap_rows": {k: sorted(c["ref"] for c in closings if c.get("plant") == k) for k in ("edge18", "tie", "amend_eq", "revert_eq")},
            "changes": [(handsets[hi], _day(days[di]), delta) for hi, di, delta in changes], "handsets": handsets, "offsets": {(h, d): offset(h, d) for h in handsets for d in days + [last + 1]},
            "served_by": {k: sorted(v) for k, v in served_by.items()}, "legacy": sorted(legacy), "planted": planted}
    return files, meta


def parse(text: str) -> int:
    return (datetime.strptime(text, "%Y-%m-%d") - EPOCH).days


# ---------------------------------------------------------------- reference computation

EPOCH = datetime(2000, 1, 1)
REGIONS = ["central", "east", "north", "south", "west"]
SEGMENTS = ["consumer", "corporate", "enterprise", "smb"]
SLOT = 60
OFFSETS = list(range(-19, 20))


class RefError(Exception):
    pass


def to_sec(text: str) -> int:
    return int((datetime.strptime(text, "%Y-%m-%dT%H:%M:%S") - EPOCH).total_seconds())


def legacy_sec(text: str) -> int:
    return int((datetime.strptime(text, "%d.%m.%Y %H:%M:%S") - EPOCH).total_seconds())


def fmt_sec(sec: int) -> str:
    return (EPOCH + timedelta(seconds=sec)).strftime("%Y-%m-%dT%H:%M:%S")


def fmt_day(day: int) -> str:
    return (EPOCH + timedelta(days=day)).strftime("%Y-%m-%d")


def parse_day(text: str) -> int:
    return (datetime.strptime(text, "%Y-%m-%d") - EPOCH).days


def table(text: str) -> list[dict[str, str]]:
    if text.startswith("﻿"):
        text = text[1:]
    rows = list(csv.reader(io.StringIO(text)))
    head = [h.strip() for h in rows[0]]
    out = []
    for raw in rows[1:]:
        if not raw or all(not v.strip() for v in raw):
            continue
        out.append({h: v.strip() for h, v in zip(head, raw)})
    return out


def dumps(obj) -> bytes:
    return (json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=True) + "\n").encode("ascii")


def half_even_cents(micro: int) -> int:
    q, r = divmod(micro, 10000)
    if r * 2 > 10000 or (r * 2 == 10000 and q % 2 == 1):
        q += 1
    return q


# ---------------------------------------------------------------- clock search

def _contrib(stamps, offset):
    c = Counter()
    for line, sod in stamps:
        c[(line, (sod + 60 * offset) // SLOT)] += 1
    return c


def search_offsets(day_closings: dict[str, list[tuple[str, int]]], reg: dict[tuple[str, int], int], limit: int = 2):
    """All assignments handset -> offset with every register count covered (up to limit)."""
    hs = sorted(day_closings)
    line_hs = defaultdict(set)
    for h in hs:
        for line, _ in day_closings[h]:
            line_hs[line].add(h)
    for (line, _slot) in reg:
        if line not in line_hs:
            return []
    contrib = {h: {o: _contrib(day_closings[h], o) for o in OFFSETS} for h in hs}
    keys_by_line = defaultdict(list)
    for key in reg:
        keys_by_line[key[0]].append(key)
    cands = {}
    for h in hs:
        keep = []
        for o in OFFSETS:
            ok = True
            for line in {ln for ln, _ in day_closings[h]}:
                others = line_hs[line] - {h}
                for key in keys_by_line[line]:
                    have = contrib[h][o][key] + sum(max(contrib[u][p][key] for p in OFFSETS) for u in others)
                    if have < reg[key]:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                keep.append(o)
        cands[h] = keep
    order = sorted(hs, key=lambda h: (len(cands[h]), h))
    sols = []
    pred = Counter()
    assigned = {}

    def maxc(u, key):
        return max(contrib[u][p][key] for p in cands[u])

    def feasible(h):
        for line in {ln for ln, _ in day_closings[h]}:
            open_hs = [u for u in line_hs[line] if u not in assigned]
            for key in keys_by_line[line]:
                if pred[key] + sum(maxc(u, key) for u in open_hs) < reg[key]:
                    return False
        return True

    def dfs(i):
        if len(sols) >= limit:
            return
        if i == len(order):
            sols.append(dict(assigned))
            return
        h = order[i]
        for o in cands[h]:
            assigned[h] = o
            pred.update(contrib[h][o])
            if feasible(h):
                dfs(i + 1)
            pred.subtract(contrib[h][o])
            del assigned[h]
            if len(sols) >= limit:
                return

    dfs(0)
    return sols


# ---------------------------------------------------------------- pipeline

def compute(files: dict[str, str], debug: dict | None = None, offset_override=None) -> dict[str, bytes]:
    cyc = json.loads(files["cycle.json"].lstrip("﻿"))
    first_day, last_day = parse_day(cyc["first_day"]), parse_day(cyc["last_day"])
    minimum = int(cyc["minimum_invoice_micro"])
    clients = {r["client"]: r for r in table(files["clients.csv"])}
    plans = {r["plan"]: r for r in table(files["plans.csv"])}
    zones = defaultdict(list)
    for r in table(files["zone_rules.csv"]):
        zones[r["zone"]].append((to_sec(r["from_utc"]), int(r["utc_offset_minutes"])))
    for z in zones.values():
        z.sort()
    holidays = {(r["region"], parse_day(r["day"])) for r in table(files["holidays.csv"])}
    catalog = {r["service"].upper(): r for r in table(files["service_catalog.csv"])}
    aliases = {r["alias"].upper(): r["service"].upper() for r in table(files["code_aliases.csv"])}
    rates = defaultdict(list)
    for r in table(files[cyc["rate_card"]]):
        to = parse_day(r["effective_to"]) if r["effective_to"] else None
        rates[(r["service"].upper(), r["tier"])].append((parse_day(r["effective_from"]), to, int(r["rate_micro_per_minute"])))

    received = {}
    for r in table(files["closings.csv"]):
        key = (r["handset"], int(r["seq"]))
        received[key] = {"ref": r["ref"], "handset": r["handset"], "seq": int(r["seq"]), "client": r["client"],
                         "code": r["service"].upper(), "stamp": to_sec(r["stamped_at"]), "worked": int(r["worked_minutes"])}
    duplicates = []
    unit = None
    for line in files["legacy_closings.txt"].lstrip("﻿").splitlines():
        if line.startswith("#"):
            if line.startswith("# duration unit:"):
                unit = line.split(":", 1)[1].strip()
            continue
        if not line.strip():
            continue
        f = [p.strip() for p in line.split("|")]
        ref, hs, seq, client, code, stamped, dur = f
        key = (hs, int(seq))
        if key in received:
            duplicates.append(ref)
            continue
        d = int(dur)
        worked = d if unit == "minutes" else -(-d // 60)
        received[key] = {"ref": ref, "handset": hs, "seq": int(seq), "client": client, "code": code.upper(),
                         "stamp": legacy_sec(stamped), "worked": worked}
    if unit not in ("seconds", "minutes"):
        raise RefError("legacy unit")

    # clock offsets per exchange day
    reg_by_day = defaultdict(dict)
    for r in table(files["exchange_register.csv"]):
        hh, mm = r["slot"].split(":")
        reg_by_day[parse_day(r["day"])][(r["line"], (int(hh) * 3600 + int(mm) * 60) // SLOT)] = int(r["calls"])
    by_day = defaultdict(lambda: defaultdict(list))
    for c in received.values():
        day, sod = divmod(c["stamp"], 86400)
        if sod < 20 * 60 or sod > 86400 - 20 * 60:
            raise RefError("stamp near midnight")
        by_day[day][c["handset"]].append((clients[c["client"]]["line"], sod))
    offset_of = {}
    if offset_override is not None:
        offset_of = offset_override(by_day, reg_by_day)
    else:
        for day in sorted(by_day):
            sols = search_offsets(by_day[day], reg_by_day.get(day, {}))
            if len(sols) != 1:
                raise RefError(f"day {fmt_day(day)}: {len(sols)} assignments")
            for h, o in sols[0].items():
                offset_of[(day, h)] = o
    if debug is not None:
        debug["offset_of"] = offset_of
        debug["by_day"] = by_day
        debug["reg_by_day"] = reg_by_day
    for c in received.values():
        c["done"] = c["stamp"] + 60 * offset_of[(c["stamp"] // 86400, c["handset"])]

    # amendments
    amends = [json.loads(x) for x in files["amendments.jsonl"].lstrip("﻿").splitlines() if x.strip()]
    by_id = {a["amendment"]: a for a in amends}
    no_effect = set()
    cancelled = set()
    for a in amends:
        if a["action"] in ("void", "minutes"):
            c = received.get((a["handset"], a["seq"]))
            if c is None or to_sec(a["issued_at"]) < c["done"]:
                no_effect.add(a["amendment"])
    for a in amends:
        if a["action"] == "revert":
            t = by_id.get(a["reverts"])
            if t is None or t["action"] not in ("void", "minutes") or to_sec(a["issued_at"]) <= to_sec(t["issued_at"]):
                no_effect.add(a["amendment"])
            else:
                cancelled.add(t["amendment"])
    live = [a for a in amends if a["action"] in ("void", "minutes") and a["amendment"] not in no_effect and a["amendment"] not in cancelled]
    live.sort(key=lambda a: (to_sec(a["issued_at"]), a["amendment"]))
    voided = set()
    for a in live:
        key = (a["handset"], a["seq"])
        if a["action"] == "void":
            voided.add(key)
        else:
            received[key]["worked"] = int(a["minutes"])

    rejected, outside, void, unrated, billed = {}, [], [], [], []
    for key, c in received.items():
        cl = clients[c["client"]]
        code = c["code"] if c["code"] in catalog else aliases.get(c["code"])
        if code is None or code not in catalog:
            rejected[c["ref"]] = "unknown_service"
            continue
        c["service"] = code
        zone = zones[cl["zone"]]
        off = None
        for frm, m in zone:
            if frm <= c["done"]:
                off = m
        local = c["done"] + 60 * off
        lday, lsod = divmod(local, 86400)
        c["lday"] = lday
        if lday < first_day or lday > last_day:
            outside.append(c["ref"])
            continue
        if key in voided:
            void.append(c["ref"])
            continue
        weekday = (EPOCH + timedelta(days=lday)).weekday()
        if weekday >= 5 or (cl["region"], lday) in holidays:
            tier = "weekend_holiday"
        elif 8 * 3600 <= lsod < 18 * 3600:
            tier = "standard"
        else:
            tier = "after_hours"
            if debug is not None and lsod == 18 * 3600:
                debug.setdefault("edge_refs", set()).add(c["ref"])
        c["tier"] = tier
        rate = None
        for frm, to, rv in rates.get((code, tier), []):
            if frm <= lday and (to is None or lday < to):
                rate = rv
        if rate is None:
            unrated.append(c["ref"])
            continue
        c["rate"] = rate
        inc = int(catalog[code]["increment_minutes"])
        c["billable"] = -(-c["worked"] // inc) * inc
        billed.append(c)

    # allowance, latest completion first
    per_client = defaultdict(list)
    for c in billed:
        c["credited"] = 0
        plan = plans[clients[c["client"]]["plan"]]
        if c["tier"] in plan["credit_tiers"].split(" "):
            per_client[c["client"]].append(c)
    for client, items in per_client.items():
        left = int(plans[clients[client]["plan"]]["included_minutes"])
        items.sort(key=lambda c: c["ref"])
        items.sort(key=lambda c: c["done"], reverse=True)
        for c in items:
            take = min(left, c["billable"])
            c["credited"] = take
            left -= take
    for c in billed:
        c["charged"] = c["billable"] - c["credited"]
        c["gross"] = c["billable"] * c["rate"]
        c["net"] = c["charged"] * c["rate"]

    billed.sort(key=lambda c: (c["done"], c["ref"]))
    out = {}
    lines = []
    for c in billed:
        cl = clients[c["client"]]
        lines.append(dumps({
            "billable_minutes": c["billable"], "charged_minutes": c["charged"], "client": c["client"],
            "completed_at": fmt_sec(c["done"]), "credited_minutes": c["credited"], "gross_micro": c["gross"],
            "handset": c["handset"], "line": cl["line"], "local_day": fmt_day(c["lday"]), "net_micro": c["net"],
            "product_line": catalog[c["service"]]["product_line"], "rate_micro_per_minute": c["rate"], "ref": c["ref"],
            "region": cl["region"], "segment": cl["segment"], "seq": c["seq"], "service": c["service"],
            "tier": c["tier"], "worked_minutes": c["worked"]}))
    out["normalized.jsonl"] = b"".join(lines)

    def group(items):
        by_tier = defaultdict(int)
        for c in items:
            by_tier[c["tier"]] += c["net"]
        gross = sum(c["gross"] for c in items)
        net = sum(c["net"] for c in items)
        return {"by_tier": dict(by_tier), "clients": sorted({c["client"] for c in items}), "closings": len(items),
                "credit_micro": gross - net, "gross_micro": gross, "net_micro": net, "net_cents": half_even_cents(net)}

    region_net = 0
    for region in REGIONS:
        g = group([c for c in billed if clients[c["client"]]["region"] == region])
        g["region"] = region
        g["in_scope"] = g["gross_micro"] >= minimum
        region_net += g["net_micro"]
        out[f"region_{region}.json"] = dumps(g)
    segment_net = 0
    for seg in SEGMENTS:
        g = group([c for c in billed if clients[c["client"]]["segment"] == seg])
        g["segment"] = seg
        g["in_scope"] = g["net_micro"] >= minimum
        segment_net += g["net_micro"]
        out[f"segment_{seg}.json"] = dumps(g)
    plines = sorted({r["product_line"] for r in catalog.values()})
    prows = []
    for pl in plines:
        items = [c for c in billed if catalog[c["service"]]["product_line"] == pl]
        prows.append({"billable_minutes": sum(c["billable"] for c in items), "closings": len(items),
                      "gross_micro": sum(c["gross"] for c in items), "net_micro": sum(c["net"] for c in items),
                      "product_line": pl})
    out["product_summary.json"] = dumps({"product_lines": prows})
    total = group(billed)
    norm_net = sum(c["net"] for c in billed)
    prod_net = sum(p["net_micro"] for p in prows)
    summary = {"by_tier": total["by_tier"], "closings_billed": total["closings"], "credit_micro": total["credit_micro"],
               "cycle": cyc["cycle"], "gross_micro": total["gross_micro"], "net_cents": total["net_cents"],
               "net_micro": total["net_micro"],
               "reconciliation": {"normalized_net_micro": norm_net, "product_net_micro": prod_net,
                                  "region_net_micro": region_net, "segment_net_micro": segment_net,
                                  "residual_micro": prod_net + region_net + segment_net - 3 * norm_net}}
    out["summary.json"] = dumps(summary)
    dq = {"amendments_without_effect": sorted(no_effect | cancelled),
          "closings_received": len(received), "duplicates": sorted(duplicates),
          "input_files": sorted(files), "outside_cycle": sorted(outside), "rejected": rejected,
          "unrated": sorted(unrated), "void": sorted(void)}
    out["data_quality.json"] = dumps(dq)
    out["__stdout__"] = "".join(f"wrote {n} {len(out[n])}\n" for n in sorted(out)).encode()
    return out


# ---------------------------------------------------------------- grading harness

_CACHE: dict = {}


def _root_only_tests_present() -> bool:
    try:
        status = Path("/tests").stat()
    except FileNotFoundError:
        return False
    return status.st_uid == 0 and (status.st_mode & 0o077) == 0


def _grant_read(argument: str) -> None:
    """Make an agent-written path readable before the uid drop.

    Agent editors write through a temp file in the same directory and rename it,
    so a program the agent wrote can land at mode 0600 (owner-only). The checks
    run that program as an unprivileged user, which then cannot open it, and a
    correct submission would score zero for a reason that has nothing to do with
    the task. The verifier runs as root, so widening the mode is always allowed
    here and it changes no graded content.
    """
    if not argument.startswith("/app"):
        return
    path = Path(argument)
    if not path.exists():
        return
    try:
        path.chmod(path.stat().st_mode | (0o555 if path.is_dir() else 0o444))
        for parent in path.parents:
            parent.chmod(parent.stat().st_mode | 0o555)
            if str(parent) == "/app":
                break
    except OSError:
        pass


def _untrusted_command(command: list[str]) -> list[str]:
    if os.name != "posix" and _root_only_tests_present():
        raise RuntimeError("verifier isolation requires POSIX uid/gid dropping")
    if os.name == "posix" and os.geteuid() != 0 and _root_only_tests_present():
        raise RuntimeError("verifier must run as root to isolate submitted code from /tests")
    if os.name == "posix" and os.geteuid() == 0:
        for argument in command:
            _grant_read(argument)
        return [*_SETPRIV, *command]
    return command


def _shipped_files() -> dict[str, str]:
    if "shipped" not in _CACHE:
        _CACHE["shipped"] = {name: zlib.decompress(base64.b64decode(blob)).decode("utf-8")
                             for name, blob in _SHIPPED_DATA.items()}
    return _CACHE["shipped"]


def _spans(reports: dict[str, bytes]) -> list[tuple[str, int, int]]:
    out = []
    for name, blob in sorted(reports.items()):
        if name.startswith(("region_", "segment_")):
            g = json.loads(blob)
            out.append((name, g["net_micro"], g["gross_micro"]))
    return out


def _with_minimum(files: dict[str, str]) -> dict[str, str]:
    """The cycle minimum of a hidden extract: the midpoint of the first partition whose net and gross straddle it."""
    spans = _spans(compute(files))
    chosen = None
    for _name, low, high in spans:
        m = low + (high - low) // 2
        if any(a < m <= b for _n, a, b in spans) and 2 <= sum(b >= m for _n, _a, b in spans) <= 7:
            chosen = m
            break
    head = json.loads(files["cycle.json"])
    head["minimum_invoice_micro"] = chosen
    files = dict(files)
    files["cycle.json"] = json.dumps(head, indent=2) + "\n"
    return files


def _hidden_files(index: int) -> dict[str, str]:
    key = ("hidden", index)
    if key not in _CACHE:
        entry = HIDDEN_EXTRACTS[index]
        files, _meta = build(entry["seed"], entry["profile"])
        docs = {n: t for n, t in _shipped_files().items() if n.endswith(".md")}
        files.update(docs)
        _CACHE[key] = _with_minimum(files)
    return _CACHE[key]


def _expected(files_key, files: dict[str, str]) -> dict[str, bytes]:
    key = ("expected", files_key)
    if key not in _CACHE:
        _CACHE[key] = compute(files)
    return _CACHE[key]


def _fresh_dir(prefix: str, mode: int = 0o755) -> Path:
    path = Path(tempfile.mkdtemp(prefix=prefix))
    path.chmod(mode)
    return path


def _stage(files: dict[str, str], parent: Path, name: str) -> Path:
    target = parent / name
    target.mkdir(parents=True)
    target.chmod(0o755)
    for fname, text in files.items():
        p = target / fname
        p.write_bytes(text.encode("utf-8"))
        p.chmod(0o644)
    return target


def _wrapper_path() -> Path:
    if "wrapper" not in _CACHE:
        holder = _fresh_dir("cdb-audit-")
        path = holder / "audited_run.py"
        path.write_text(_AUDIT_WRAPPER, encoding="utf-8")
        path.chmod(0o644)
        _CACHE["wrapper"] = path
    return _CACHE["wrapper"]


def _run(data_dir: Path, out_dir: Path, cwd: Path) -> dict:
    """One audited call of the delivered program, timed from the parent."""
    result = {"ok": False, "stdout": b"", "reports": {}, "events": [], "elapsed": None}
    if not PROGRAM.is_file():
        return result
    read_fd, write_fd = os.pipe()
    env = {"PATH": "/usr/local/bin:/usr/bin:/bin", "PYTHONDONTWRITEBYTECODE": "1", "LANG": "C.UTF-8"}
    command = _untrusted_command([sys.executable, str(_wrapper_path()), str(write_fd), str(PROGRAM), str(data_dir), str(out_dir)])
    started = time.monotonic()
    try:
        proc = subprocess.Popen(command, cwd=str(cwd), env=env, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL,
                                pass_fds=(write_fd,), start_new_session=True)
    except OSError:
        os.close(read_fd)
        os.close(write_fd)
        return result
    os.close(write_fd)
    os.set_blocking(read_fd, False)
    log = io.BytesIO()
    stdout = b""
    timed_out = False
    with os.fdopen(read_fd, "rb") as sink:
        try:
            stdout, _ = proc.communicate(timeout=CALL_LIMIT_SEC)
        except subprocess.TimeoutExpired:
            timed_out = True
        finally:
            # Kill the whole session so no child left behind can hold a pipe open.
            try:
                os.killpg(proc.pid, signal.SIGKILL)
            except OSError:
                pass
        if timed_out:
            try:
                stdout, _ = proc.communicate(timeout=10)
            except subprocess.TimeoutExpired:
                stdout = b""
        try:
            log.write(sink.read() or b"")
        except OSError:
            pass
    result["elapsed"] = time.monotonic() - started
    for line in log.getvalue().decode("utf-8", "replace").splitlines():
        try:
            result["events"].append(json.loads(line))
        except ValueError:
            continue
    result["stdout"] = stdout or b""
    if not timed_out and proc.returncode == 0:
        result["ok"] = True
    reports = {}
    for name in REPORT_NAMES:
        try:
            reports[name] = (out_dir / name).read_bytes()
        except OSError:
            continue
    result["reports"] = reports
    result["data_dir"] = str(data_dir)
    result["out_dir"] = str(out_dir)
    return result


def _run_extract(files: dict[str, str], tag: str) -> dict:
    root = _fresh_dir(f"cdb-{tag}-")
    data_dir = _stage(files, root, "extract")
    out_parent = _fresh_dir(f"cdb-{tag}-out-", 0o777)
    out_dir = out_parent / "reports"
    out_dir.mkdir()
    out_dir.chmod(0o777)
    cwd = _fresh_dir(f"cdb-{tag}-cwd-")
    return _run(data_dir, out_dir, cwd)


def _shipped_runs() -> dict:
    """Two runs with identical paths and one at a different extract path, working directory and output directory."""
    if "runs" not in _CACHE:
        files = _shipped_files()
        root = _fresh_dir("cdb-ship-")
        data_dir = _stage(files, root, "cycle")
        out_parent = _fresh_dir("cdb-ship-out-", 0o777)
        out_dir = out_parent / "o"
        cwd = _fresh_dir("cdb-ship-cwd-")
        runs = []
        for _ in range(2):
            if out_dir.exists():
                shutil.rmtree(out_dir)
            out_dir.mkdir()
            out_dir.chmod(0o777)
            first = _run(data_dir, out_dir, cwd)
            runs.append(first)
        root2 = _fresh_dir("cdb-elsewhere-")
        nested = root2 / "deeper" / "copy of extract"
        nested.parent.mkdir()
        nested.parent.chmod(0o755)
        data2 = _stage(files, nested.parent, nested.name)
        out2_parent = _fresh_dir("cdb-elsewhere-out-", 0o777)
        out2 = out2_parent / "other reports"
        out2.mkdir()
        out2.chmod(0o777)
        cwd2 = _fresh_dir("cdb-elsewhere-cwd-")
        runs.append(_run(data2, out2, cwd2))
        _CACHE["runs"] = runs
    return _CACHE["runs"]


def _hidden_run(index: int) -> dict:
    key = ("hidden-run", index)
    if key not in _CACHE:
        _CACHE[key] = _run_extract(_hidden_files(index), f"h{index:02d}")
    return _CACHE[key]


def _hidden_exact(index: int) -> bool:
    try:
        files = _hidden_files(index)
        expected = _expected(("hidden", index), files)
        run = _hidden_run(index)
    except Exception:
        return False
    if not run["ok"] or run["elapsed"] is None or run["elapsed"] > CALL_LIMIT_SEC:
        return False
    return all(run["reports"].get(name) == expected[name] for name in REPORT_NAMES)


def _shipped_artifact_exact(names: list[str]) -> bool:
    try:
        expected = _expected("shipped", _shipped_files())
        return all((OUT_DIR / name).read_bytes() == expected[name] for name in names)
    except Exception:
        return False


def _all_runs() -> list[dict]:
    runs = list(_shipped_runs())
    for i in range(len(HIDDEN_EXTRACTS)):
        runs.append(_hidden_run(i))
    return runs


def _bad_access(run: dict) -> bool:
    allowed_read = [run.get("data_dir", ""), run.get("out_dir", ""), str(OUT_DIR), sys.base_prefix, sys.prefix,
                    str(_wrapper_path().parent)]
    out_dir = run.get("out_dir", "")
    for kind, path, writes in run["events"]:
        if kind == "socket":
            continue
        if kind == "process":
            continue
        real = os.path.normpath(path)
        inside = lambda root: bool(root) and (real == root or real.startswith(root.rstrip("/") + "/"))
        if writes is True and not inside(out_dir) and real != "/dev/null":
            return True
        if any(inside(r) for r in _FORBIDDEN_ROOTS) and not any(inside(a) for a in allowed_read):
            return True
    return False


def _graded_literals() -> set:
    expected = _expected("shipped", _shipped_files())
    docs = "\n".join(t for n, t in _shipped_files().items() if n.endswith(".md"))
    values: set = set()

    def walk(v):
        if isinstance(v, dict):
            for k, x in v.items():
                walk(k)
                walk(x)
        elif isinstance(v, list):
            for x in v:
                walk(x)
        elif isinstance(v, bool):
            return
        elif isinstance(v, int) and abs(v) >= 100000:
            values.add(v)
        elif isinstance(v, str) and len(v) >= 6 and v not in docs:
            values.add(v)

    for name, blob in expected.items():
        if name == "normalized.jsonl":
            for line in blob.decode().splitlines():
                walk(json.loads(line))
        elif name.endswith(".json"):
            walk(json.loads(blob))
    return values


def _program_tree():
    try:
        return ast.parse(PROGRAM.read_text(encoding="utf-8"))
    except Exception:
        return None


